CREATE OR REPLACE FUNCTION public.wake_timezone_reschedule() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE a public.alarms; BEGIN IF NEW.reward_timezone IS DISTINCT FROM OLD.reward_timezone THEN IF NOT pg_try_advisory_xact_lock(hashtextextended(NEW.id::text,74010)) OR NOT pg_try_advisory_xact_lock(hashtextextended(NEW.id::text,74011)) THEN RAISE EXCEPTION 'Alarm verification is busy. Retry the timezone change.' USING ERRCODE='40001'; END IF; IF EXISTS(SELECT 1 FROM public.alarm_events WHERE user_id=NEW.id AND status='ringing') THEN RAISE EXCEPTION 'Solve the ringing alarm before changing timezone'; END IF; FOR a IN SELECT * FROM public.alarms WHERE user_id=NEW.id AND label='AXEN Wake Protocol' AND is_active AND wake_saved_at IS NOT NULL FOR UPDATE LOOP UPDATE public.alarm_events SET status='expired' WHERE alarm_id=a.id AND status='scheduled' AND NOT is_test; UPDATE public.alarms SET wake_timezone=NEW.reward_timezone,wake_saved_at=now(),wake_next_fire_at=public.wake_next_fire(a.time,NEW.reward_timezone) WHERE id=a.id; PERFORM public.wake_create_occurrence(a.id); END LOOP; END IF; RETURN NEW; END; $$;
COMMENT ON FUNCTION public.wake_timezone_reschedule() IS 'Retry rather than deadlock if verification holds user locks; ringing snapshots cannot be bypassed by timezone changes. Upcoming UTC occurrences are recalculated with the new IANA timezone.';